// A licence number is shown (and live mode allowed) only when it is exactly 14 digits and is not our registration
// number pasted by mistake. Anything else counts as "no licence".
export const FSSAI_LIC_RE = /^\d{14}$/;
export const isFssaiLicence = (v) => typeof v === "string" && FSSAI_LIC_RE.test(v) && v !== SELLER.fssaiRegNo;
